   "      <div class=\"field\"><label>RFC (opcional)</label><input id=\"pf_rfc\" value=\"${escapeHtml(p.rfc || '')}\" style=\"text-transform:uppercase;\" /></div>\n      <div class=\"field\"><label>CURP (opcional)</label><input id=\"pf_curp\" value=\"${escapeHtml(p.curp || '')}\" style=\"text-transform:uppercase;\" /></div>\n    </div>\n    <details ${id && (p.nss || p.numero_ine || p.fecha_nacimiento || p.jefe_directo) ? 'open' : ''} style=\"margin:0 0 10px;\">\n      <summary style=\"cursor:pointer; font-size:13px; font-weight:700; margin-bottom:8px;\">📁 Expediente (IMSS, INE, nacimiento, jefe…)</summary>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Jefe directo</label><input id=\"pf_jefe\" value=\"${escapeHtml(p.jefe_directo || '')}\" /></div>\n        <div class=\"field\"><label>Correo electrónico</label><input id=\"pf_email\" type=\"email\" value=\"${escapeHtml(p.email || '')}\" style=\"text-transform:none;\" /></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>NSS</label><input id=\"pf_nss\" inputmode=\"numeric\" value=\"${escapeHtml(p.nss || '')}\" /></div>\n        <div class=\"field\"><label>No. de INE</label><input id=\"pf_ine\" value=\"${escapeHtml(p.numero_ine || '')}\" style=\"text-transform:uppercase;\" /></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Fecha de nacimiento${p.edad != null ? ` (${p.edad} años)` : ''}</label><input type=\"date\" id=\"pf_nac\" value=\"${p.fecha_nacimiento || ''}\" /></div>\n        <div class=\"field\"><label>Estado civil</label><input id=\"pf_civil\" list=\"pf_civiles\" value=\"${escapeHtml(p.estado_civil || '')}\" />\n          <datalist id=\"pf_civiles\">${['Soltero','Soltera','Casado','Casada','Union libre','Divorciado','Divorciada','Viudo','Viuda'].map(x => `<option value=\"${x}\">`).join('')}</datalist></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Bono semanal</label><input type=\"number\" id=\"pf_bono\" min=\"0\" step=\"0.01\" value=\"${p.bono_semanal ?? ''}\" /></div>\n        <div class=\"field\"><label>Seguro IMSS</label><input id=\"pf_imss\" list=\"pf_imss_op\" value=\"${escapeHtml(p.seguro_imss || '')}\" placeholder=\"SI / A PRUEBA / NO…\" />\n          <datalist id=\"pf_imss_op\">${['SI','NO','A PRUEBA','PARCIAL','JUBILADO','MENOR'].map(x => `<option value=\"${x}\">`).join('')}</datalist></div>\n      </div>\n      <div class=\"row-2\">\n        <div class=\"field\"><label>Fecha de alta en el IMSS</label><input type=\"date\" id=\"pf_alta_imss\" value=\"${p.fecha_alta_imss || ''}\" /></div>\n        <div class=\"field\"><label>Razón social</label><input id=\"pf_razon\" value=\"${escapeHtml(p.razon_social || '')}\" /></div>\n      </div>\n    </details>\n    ${!id ? `<label style=\"font-size:13px; display:flex; gap:6px; align-items:flex-start; margin:4px 0 8px;\">\n        <input type=\"checkbox\" id=\"pf_checadores\" style=\"width:auto; margin-top:3px;\" ${(d.checadores || []).length ? 'checked' : 'disabled'} />\n        <span>Darlo de alta en los checadores con este número y su nombre${(d.checadores || []).length ? ` (${d.checadores.map(escapeHtml).join(', ')})` : ' — <i>todavía no hay checadores conectados</i>'}.\n"
